<script>
(function () {
    var match = window.location.pathname.match(/order-received\/(\d+)/);
    if (!match) return;

    var orderId = match[1];
    var key = new URLSearchParams(window.location.search).get('key') || '';
    var summaryEl = document.getElementById('dpv-order-summary');

    fetch('/wp-json/dpv/v1/order-tracking-data/' + orderId + '?key=' + encodeURIComponent(key))
        .then(function (res) { return res.json(); })
        .then(function (data) {

            if (summaryEl) {
                if (data.found) {
                    var formatter = new Intl.NumberFormat('nl-NL', {
                        minimumFractionDigits: 2,
                        maximumFractionDigits: 2
                    });

                    var emailRow = data.email
                        ? '<div class="dpv-order-row">'
                          + '<span class="label">E-mailadres</span>'
                          + '<span class="value-email">' + escHtml(data.email) + '</span>'
                          + '</div>'
                        : '';

                    var transactionRow = data.order_number
                        ? '<div class="dpv-order-row">'
                          + '<span class="label">Reserveringsnummer</span>'
                          + '<span class="value-id">' + escHtml(String(data.order_number)) + '</span>'
                          + '</div>'
                        : '';

                    var totalRow = (data.total !== undefined && data.total !== null)
                        ? '<div class="dpv-order-row total">'
                          + '<span class="label">Totaalbedrag</span>'
                          + '<span class="value">'
                          + '<span class="currency">€</span>'
                          + '<span class="amount">' + formatter.format(data.total) + '</span>'
                          + '</span>'
                          + '</div>'
                        : '';

                    summaryEl.innerHTML =
                        '<div class="dpv-order-summary-title">Jouw reserveringsoverzicht</div>'
                        + emailRow
                        + transactionRow
                        + totalRow;
                } else {
                    summaryEl.style.display = 'none';
                }
            }

            if (!data.found || data.already_tracked) return;

            var payload, eventName;
            if (data.is_paid) {
                eventName = 'purchase';
                payload = {
                    transaction_id: data.order_number,
                    value:          data.total,
                    currency:       data.currency,
                    shipping:       data.shipping,
                    tax:            data.tax,
                    items:          data.items
                };
            } else if (data.is_quote) {
                eventName = 'conversion';
                payload = {
                    'send_to':        'AW-17727220476/xJYcCPulrsgcEPzV_4RC',
                    'value':          data.total,
                    'currency':       data.currency,
                    'transaction_id': data.order_number
                };
            } else {
                return;
            }

            if (typeof gtag === 'function') {
                gtag('event', eventName, payload);
            } else {
                window.dataLayer = window.dataLayer || [];
                window.dataLayer.push(Object.assign({ event: eventName }, payload));
            }
        })
        .catch(function () {
            if (summaryEl) summaryEl.style.display = 'none';
        });

    function escHtml(str) {
        return str
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#39;');
    }
})();
</script>","eael_tooltip_section_content":"I am a tooltip","eael_ext_content_protection_password_placeholder":"Enter Password","eael_ext_content_protection_password_submit_btn_txt":"Submit","eael_ext_content_protection_password_incorrect_message":"Password does not match.","eael_cl_logics":[{"_id":"ac930e7","dynamic_field_custom_separator":"|"}],"as_bs_lists":[],"as_bs_lists_h":[],"as_ts_lists":[],"as_ts_lists_h":[],"as_ds_lists":[],"as_ds_lists_h":[]},"elements":[],"widgetType":"html"}],"isInner":false}]
